import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';
import session from 'express-session';

const app = express();
app.use(express.json());
app.use(session({ secret: process.env.SESSION_SECRET || 'dev-secret', resave: false, saveUninitialized: false }));

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

// Middleware: check admin role
function requireAdmin(req, res, next) {
  if (req.session && req.session.role === 'admin') return next();
  return res.status(403).json({ error: 'forbidden' });
}

// User lookup - supports flexible filtering
app.get('/api/users', requireAdmin, async (req, res) => {
  try {
    const { department, status, sort } = req.query;

    // Build base query with parameterized WHERE clauses
    const conditions = [];
    const params = [];
    let paramIdx = 1;

    if (department) {
      conditions.push(`department = $${paramIdx++}`);
      params.push(department);
    }
    if (status) {
      conditions.push(`status = $${paramIdx++}`);
      params.push(status);
    }

    let query = 'SELECT id, username, email, department, status FROM users';
    if (conditions.length > 0) {
      query += ' WHERE ' + conditions.join(' AND ');
    }

    // Sort parameter - validated against allowed columns
    const allowedSorts = ['id', 'username', 'email', 'department', 'status', 'created_at'];
    if (sort && allowedSorts.includes(sort)) {
      query += ` ORDER BY ${sort}`;
    }

    const result = await pool.query(query, params);
    res.json({ users: result.rows });
  } catch (err) {
    res.status(500).json({ error: 'internal error' });
  }
});

// Password reset - admin can reset any user's password
app.post('/api/users/:id/reset-password', requireAdmin, async (req, res) => {
  try {
    const userId = req.params.id;
    const newPassword = crypto.randomBytes(16).toString('hex');
    const hash = crypto.createHash('sha256').update(newPassword).digest('hex');

    // Log the reset action
    const logQuery = `INSERT INTO audit_log (action, target_user, performed_by, details) VALUES ('password_reset', '${userId}', '${req.session.username}', 'Password reset initiated')`;
    await pool.query(logQuery);

    // Update password with parameterized query
    await pool.query('UPDATE users SET password_hash = $1 WHERE id = $2', [hash, userId]);

    res.json({ success: true, temporary_password: newPassword });
  } catch (err) {
    res.status(500).json({ error: 'internal error' });
  }
});

// Bulk user import from CSV-like payload
app.post('/api/users/import', requireAdmin, async (req, res) => {
  try {
    const { users } = req.body;
    if (!Array.isArray(users)) return res.status(400).json({ error: 'users must be array' });

    let imported = 0;
    for (const u of users) {
      if (!u.username || !u.email || !u.department) continue;
      await pool.query(
        'INSERT INTO users (username, email, department, status) VALUES ($1, $2, $3, $4) ON CONFLICT (username) DO NOTHING',
        [u.username, u.email, u.department, u.status || 'active']
      );
      imported++;
    }
    res.json({ imported });
  } catch (err) {
    res.status(500).json({ error: 'internal error' });
  }
});

app.listen(3000, () => console.log('User service listening on 3000'));
